// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createOwner, createOwnerPet, getPet, updatePet } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:9966");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Request Body
    const ownersPostRequestBody: string = `{
        "address": "1 Test Way",
        "city": "Madison",
        "firstName": "Nick",
        "lastName": "Nameson",
        "telephone": "6085550000"
    }`;

    const ownersPostResponse = await createOwner(client, URL_localhost, ownersPostRequestBody);

    expect(ownersPostResponse.statusCode, 'status code').toBe(201);

    expect(getResponseValue(ownersPostResponse, "firstName"), 'firstName').toBe("Nick");
    expect(getResponseValue(ownersPostResponse, "lastName"), 'lastName').toBe("Nameson");
    expect(getResponseValue(ownersPostResponse, "address"), 'address').toBe("1 Test Way");
    expect(getResponseValue(ownersPostResponse, "city"), 'city').toBe("Madison");
    expect(getResponseValue(ownersPostResponse, "telephone"), 'telephone').toBe("6085550000");
    expect(getResponseValue(ownersPostResponse, "id"), 'id').toBeGreaterThan(0);

    // Request Body
    const petsPostRequestBody: string = `{
        "birthDate": "2010-09-07",
        "name": "Leo",
        "nickname": "Bud",
        "type": {
            "id": 1,
            "name": "cat"
        }
    }`;

    const petsPostResponse = await createOwnerPet(
        client,
        URL_localhost,
        getResponseValue(ownersPostResponse, "id"),
        petsPostRequestBody
    );

    expect(petsPostResponse.statusCode, 'status code').toBe(201);

    expect(getResponseValue(petsPostResponse, "name"), 'name').toBe("Leo");
    expect(getResponseValue(petsPostResponse, "nickname"), 'nickname').toBe("Bud");
    expect(getResponseValue(petsPostResponse, "birthDate"), 'birthDate').toBe("2010-09-07");
    expect(getResponseValue(petsPostResponse, "type.id"), 'type.id').toBe(1);
    expect(getResponseValue(petsPostResponse, "type.name"), 'type.name').toBe("cat");
    expect(getResponseValue(petsPostResponse, "ownerId"), 'ownerId').toBe(getResponseValue(ownersPostResponse, "id"));
    expect(getResponseValue(petsPostResponse, "id"), 'id').toBeGreaterThan(0);

    const petsPetsGetResponse = await getPet(
        client,
        URL_localhost,
        getResponseValue(petsPostResponse, "id")
    );

    expect(petsPetsGetResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(petsPetsGetResponse, "id"), 'id').toBe(getResponseValue(petsPostResponse, "id"));
    expect(getResponseValue(petsPetsGetResponse, "name"), 'name').toBe("Leo");
    expect(getResponseValue(petsPetsGetResponse, "nickname"), 'nickname').toBe("Bud");
    expect(getResponseValue(petsPetsGetResponse, "birthDate"), 'birthDate').toBe("2010-09-07");
    expect(getResponseValue(petsPetsGetResponse, "type.name"), 'type.name').toBe("cat");
    expect(getResponseValue(petsPetsGetResponse, "ownerId"), 'ownerId').toBe(getResponseValue(ownersPostResponse, "id"));

    // Request Body
    const petsPetsPutRequestBody: string = `{
        "birthDate": "2010-09-07",
        "id": 815502,
        "name": "Leo",
        "nickname": "Buddy",
        "ownerId": 907341,
        "type": {
            "id": 1,
            "name": "cat"
        },
        "visits": []
    }`;

    const petsPetsPutResponse = await updatePet(
        client,
        URL_localhost,
        getResponseValue(petsPostResponse, "id"),
        petsPetsPutRequestBody,
        {
            "birthDate": getResponseValue(petsPetsGetResponse, "birthDate"),
            "id": getResponseValue(petsPostResponse, "id"),
            "name": getResponseValue(petsPetsGetResponse, "name"),
            "ownerId": getResponseValue(petsPostResponse, "ownerId"),
            "type.id": getResponseValue(petsPetsGetResponse, "type.id"),
            "type.name": getResponseValue(petsPetsGetResponse, "type.name")
        }
    );

    expect(petsPetsPutResponse.statusCode, 'status code').toBe(204);

    const petsPetsGet1Response = await getPet(
        client,
        URL_localhost,
        getResponseValue(petsPostResponse, "id")
    );

    expect(petsPetsGet1Response.statusCode, 'status code').toBe(200);

    expect(getResponseValue(petsPetsGet1Response, "id"), 'id').toBe(getResponseValue(petsPostResponse, "id"));
    expect(getResponseValue(petsPetsGet1Response, "nickname"), 'nickname').toBe("Buddy");
    expect(getResponseValue(petsPetsGet1Response, "name"), 'name').toBe("Leo");
    expect(getResponseValue(petsPetsGet1Response, "birthDate"), 'birthDate').toBe("2010-09-07");
    expect(getResponseValue(petsPetsGet1Response, "type.name"), 'type.name').toBe("cat");
    expect(getResponseValue(petsPetsGet1Response, "ownerId"), 'ownerId').toBe(getResponseValue(ownersPostResponse, "id"));
});
